CREATE OR REPLACE FUNCTION public.supprimer_photo_support_v0129_lot3(p_photo_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_photo record;
  v_role text;
  v_actor_client bigint;
  v_client bigint;
  v_replacement record;
  v_id_type text;
begin

  if auth.uid() is null then
    raise exception 'unauthorized' using errcode='42501';
  end if;
  begin
    select u.role, u.client_id into strict v_role, v_actor_client
    from public.utilisateurs u
    where u.auth_user_id=auth.uid() and lower(coalesce(u.statut,''))='actif'
    for share;
  exception when no_data_found or too_many_rows then
    raise exception 'unauthorized' using errcode='42501';
  end;
  if v_role is null or v_role not in ('Administrateur') then
    raise exception 'forbidden' using errcode='42501';
  end if;
  -- Internal staff may have global scope (explicitly approved).
  -- A populated profile client always restricts that scope.


  if to_regclass('public.support_photos') is null then
    raise exception 'La table support_photos est absente.';
  end if;

  select data_type into v_id_type
  from information_schema.columns
  where table_schema='public' and table_name='support_photos' and column_name='id';

  if v_id_type in ('uuid') then
    execute 'select * from public.support_photos where id = $1::uuid for update'
      into v_photo using p_photo_id;
  elsif v_id_type in ('bigint','integer','smallint','numeric') then
    execute 'select * from public.support_photos where id::text = $1 for update'
      into v_photo using p_photo_id;
  else
    execute 'select * from public.support_photos where id::text = $1 for update'
      into v_photo using p_photo_id;
  end if;

  if v_photo is null then
    raise exception 'resource_not_found' using errcode='P0002';
  end if;


  select client_id into v_client from public.infrastructures where support_id=v_photo.support_id for update;
  if not found then raise exception 'resource_not_found' using errcode='P0002'; end if;

  if v_client is null or not exists(select 1 from public.clients where id=v_client)
     or (v_actor_client is not null and v_actor_client is distinct from v_client) then
    raise exception 'client_scope_denied' using errcode='42501';
  end if;

  if v_photo.client_id is null or v_photo.client_id is distinct from v_client then
    raise exception 'cross_client_denied' using errcode='42501';
  end if;
  if v_photo.campagne_id is not null and not exists(
    select 1 from public.campagnes_maitres where id=v_photo.campagne_id and client_id=v_client
  ) then raise exception 'cross_client_denied' using errcode='42501'; end if;

  execute 'delete from public.support_photos where id::text = $1' using p_photo_id;

  execute $q$
    select * from public.support_photos
    where support_id::text = $1
    order by coalesce(prise_le, created_at, now()) desc
    limit 1
  $q$ into v_replacement using v_photo.support_id::text;


  if v_replacement.id is not null and v_replacement.client_id is distinct from v_client then
    raise exception 'cross_client_denied' using errcode='42501';
  end if;
  if to_regclass('public.infrastructures') is not null then
    begin
      execute $q$
        update public.infrastructures
        set photo_principale_url=$1,
            photo_miniature_url=$2
        where support_id::text=$3
      $q$ using
        case when v_replacement is null then null else v_replacement.photo_url end,
        case when v_replacement is null then null else coalesce(v_replacement.thumbnail_url,v_replacement.photo_url) end,
        v_photo.support_id::text;
    exception when undefined_column then
      null;
    end;
  end if;

  insert into public.photo_action_log(action,photo_id,support_id,nom_fichier,details,user_id)
  values ('SUPPRESSION',p_photo_id,v_photo.support_id::text,v_photo.nom_fichier,
    jsonb_build_object('storage_path',v_photo.storage_path,'replacement_id',
      case when v_replacement is null then null else v_replacement.id::text end),auth.uid());

  return jsonb_build_object(
    'ok',true,
    'photo_id',p_photo_id,
    'support_id',v_photo.support_id::text,
    'storage_path',v_photo.storage_path,
    'replacement_id',case when v_replacement is null then null else v_replacement.id::text end
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_edt_progress_from_work_order()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.edt_id is not null then
    perform public.refresh_edt_progress(new.edt_id);
  end if;
  if tg_op = 'UPDATE' and old.edt_id is distinct from new.edt_id and old.edt_id is not null then
    perform public.refresh_edt_progress(old.edt_id);
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_legacy_visual_edt()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
 IF TG_OP='UPDATE' AND NEW.edt_phase_id IS NOT DISTINCT FROM OLD.edt_phase_id THEN RETURN NEW;END IF;
 IF TG_OP='UPDATE' AND OLD.edt_phase_id IS NOT NULL AND NEW.edt_phase_id IS NULL THEN
  DELETE FROM public.visual_edt_associations WHERE visual_id=NEW.id AND phase_id=OLD.edt_phase_id;
 END IF;
 IF NEW.edt_phase_id IS NOT NULL THEN
  INSERT INTO public.visual_edt_associations(visual_id,edt_id,phase_id) SELECT NEW.id,p.edt_id,p.id FROM public.edt_phases p WHERE p.id=NEW.edt_phase_id ON CONFLICT(visual_id,edt_id) DO NOTHING;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.sync_photo_current_visual_v132p0()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  new.captured_at := coalesce(new.captured_at,new.prise_le,now());
  new.prise_le := coalesce(new.prise_le,new.captured_at);
  new.original_filename := coalesce(new.original_filename,new.nom_fichier);
  new.normalized_filename := coalesce(new.normalized_filename,new.nom_fichier);
  new.storage_bucket := coalesce(nullif(new.storage_bucket,''),
    case
      when coalesce(new.photo_url,'') like '%/terrain-photos/%' then 'terrain-photos'
      when coalesce(new.photo_url,'') like '%/support-photos/%' then 'support-photos'
      else 'support-photos'
    end);
  new.source := coalesce(nullif(new.source,''),
    case when new.storage_bucket='terrain-photos' then 'terrain' else 'legacy' end);
  new.updated_at := now();
  if tg_op='INSERT' or new.type_photo is distinct from old.type_photo then
    new.is_current_visual := lower(coalesce(new.type_photo,''))='inspection'
      or (lower(coalesce(new.type_photo,''))='installation' and new.est_principale);
  end if;
  new.est_principale := new.is_current_visual;
  if new.is_current_visual then
    update public.support_photos set is_current_visual=false,est_principale=false,updated_at=now()
      where support_id=new.support_id and id<>new.id and (is_current_visual or est_principale);
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.terrain_photo_access_prepared(p_path text, p_action text, p_owner text DEFAULT NULL::text, p_created timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid(); v_role text; v_client bigint; v_support text; v_owner bigint;
begin
  if v_uid is null or p_action is null or p_action not in ('read','insert','delete')
     or p_path is null or p_path !~ '^[A-Za-z0-9_-]+/'
     or p_path ~ '(^|/)[.][.]?(/|$)|//|[?#%]' then return false; end if;
  v_role:=public.tos_current_role();
  if v_role is null then return false; end if;
  select u.client_id into v_client from public.utilisateurs u where u.auth_user_id=v_uid and lower(u.statut)='actif';
  v_support:=case when split_part(p_path,'/',1)='supports' then split_part(p_path,'/',2) else split_part(p_path,'/',1) end;
  select i.client_id into v_owner from public.infrastructures i join public.clients c on c.id=i.client_id where i.support_id=v_support;
  if v_owner is null then return false; end if;
  if exists(select 1 from public.support_photos p
    where ((p.storage_bucket='terrain-photos' and p.storage_path=p_path)
      or p.photo_url='terrain-photos/'||p_path
      or split_part(p.photo_url,'/storage/v1/object/public/terrain-photos/',2)=p_path)
    and (p.client_id is distinct from v_owner or p.support_id is distinct from v_support
      or (p.campagne_id is not null and not exists(select 1 from public.campagnes_maitres c where c.id=p.campagne_id and c.client_id=v_owner)))) then return false; end if;
  if v_role in ('Administrateur','Coordonnateur','Installateur') then
    if v_client is not null and v_client<>v_owner then return false; end if;
    if p_action in ('read','insert') then return true; end if;
    if v_role='Administrateur' then return true; end if;
    -- Upload rollback only: internal uploader, no registered photo left.
    return p_owner=v_uid::text and p_created>now()-interval '10 minutes'
      and not exists(select 1 from public.inspections_terrain x where x.photo_path=p_path or x.photo_url='terrain-photos/'||p_path or split_part(x.photo_url,'/storage/v1/object/public/terrain-photos/',2)=p_path)
      and not exists(select 1 from public.infrastructures i where i.photo_principale_url='terrain-photos/'||p_path or i.photo_miniature_url='terrain-photos/'||p_path or split_part(i.photo_principale_url,'/storage/v1/object/public/terrain-photos/',2)=p_path or split_part(i.photo_miniature_url,'/storage/v1/object/public/terrain-photos/',2)=p_path)
      and not exists(select 1 from public.support_photos p
      where (p.storage_bucket='terrain-photos' and p.storage_path=p_path)
         or p.photo_url='terrain-photos/'||p_path
         or split_part(p.photo_url,'/storage/v1/object/public/terrain-photos/',2)=p_path);
  end if;
  if p_action<>'read' or v_role not in ('Client','Client-Admin') or v_client is null or v_client<>v_owner then return false; end if;
  return exists(select 1 from public.support_photos p
    left join public.campagnes_maitres c on c.id=p.campagne_id and c.client_id=p.client_id
    where p.support_id=v_support and p.client_id=v_owner and (p.client_visible OR public.portal_view_allowed('Photos et inventaire')) and p.deleted_at is null
      and ((p.storage_bucket='terrain-photos' and p.storage_path=p_path)
        or p.photo_url='terrain-photos/'||p_path
        or split_part(p.photo_url,'/storage/v1/object/public/terrain-photos/',2)=p_path)
      and (public.portal_view_allowed('Photos et inventaire') or p.campagne_id is null or (c.client_published and (v_role='Client-Admin' or exists(select 1 from public.client_campaign_access a where a.client_id=v_client and a.campaign_id=c.id
        and (a.user_id is null or a.user_id=v_uid))))));
end $function$

CREATE OR REPLACE FUNCTION public.transition_edt_phase_v133(p_phase_id bigint, p_target_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.edt_phases%rowtype;e public.suivi_des_edt%rowtype;v_current text;v_target text;v_parent text;v_updated public.edt_phases%rowtype;
BEGIN
IF (auth.uid() IS NOT NULL AND public.tos_current_role() IN ('Administrateur','Coordonnateur')) IS NOT TRUE THEN RAISE EXCEPTION 'canonical_rpc_role_denied' USING ERRCODE='42501';END IF;
IF (NOT EXISTS(SELECT 1 FROM public.utilisateurs actor_profile WHERE actor_profile.auth_user_id=auth.uid() AND lower(coalesce(actor_profile.statut,''))='actif' AND actor_profile.client_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.clients actor_owner WHERE actor_owner.id=actor_profile.client_id))) IS NOT TRUE THEN RAISE EXCEPTION 'canonical_actor_client_invalid' USING ERRCODE='42501';END IF;
IF (EXISTS(SELECT 1 FROM public.edt_phases sec_phase JOIN public.suivi_des_edt sec_edt ON sec_edt.id=sec_phase.edt_id WHERE sec_phase.id=p_phase_id AND (sec_phase.client_id IS NULL OR sec_phase.client_id=sec_edt.client_id) AND public.tos_table_resource_scope(sec_edt.client_id,NULL,sec_edt.campagne_id,NULL,false))) IS NOT TRUE THEN RAISE EXCEPTION 'phase_scope_denied' USING ERRCODE='42501';END IF;

BEGIN

 if auth.uid() is null then raise exception 'authentication_required' using errcode='28000';end if;
 if public.current_app_role() not in ('Administrateur','Coordonnateur') then raise exception 'permission_denied' using errcode='42501';end if;
 select * into p from public.edt_phases where id=p_phase_id for update;
 if not found or p.phase_type not in ('installation','retrait') then raise exception 'phase_not_found';end if;
 select * into e from public.suivi_des_edt where id=p.edt_id for update;if not found or e.archived_at is not null then raise exception 'edt_not_available';end if;
 v_current:=case lower(p.statut) when 'planifie' then 'planifiee' when 'termine' then 'terminee' when 'ferme' then 'fermee' else lower(p.statut) end;
 v_target:=case lower(p_target_status) when 'planifie' then 'planifiee' when 'termine' then 'terminee' when 'ferme' then 'fermee' else lower(p_target_status) end;
 if not ((v_current='planifiee' and v_target='en_cours') or (v_current='en_cours' and v_target='terminee') or (v_current='terminee' and v_target='fermee') or (v_current='fermee' and v_target='terminee')) then
   raise exception 'invalid_phase_transition:%->%',v_current,v_target using errcode='22023';
 end if;
 update public.edt_phases set statut=v_target,
   date_debut_reelle=case when v_target='en_cours' then coalesce(date_debut_reelle,now()) else date_debut_reelle end,
   date_fin_reelle=case when v_target='terminee' and v_current='en_cours' then coalesce(date_fin_reelle,now()) when v_current='fermee' then null else date_fin_reelle end,
   closed_at=case when v_target='fermee' then now() when v_current='fermee' then null else closed_at end,
   closed_by=case when v_target='fermee' then auth.uid() when v_current='fermee' then null else closed_by end,
   progression=case v_target when 'planifiee' then 0 when 'en_cours' then greatest(progression,1) else 100 end,updated_at=now()
 where id=p.id returning * into v_updated;
 v_parent:=case when not exists(select 1 from public.edt_phases x where x.edt_id=p.edt_id and x.phase_type in ('installation','retrait') and x.statut<>'fermee')
                       and exists(select 1 from public.edt_phases x where x.edt_id=p.edt_id and x.phase_type='installation' and x.statut='fermee')
                       and exists(select 1 from public.edt_phases x where x.edt_id=p.edt_id and x.phase_type='retrait' and x.statut='fermee')
                  then 'Termine'
                  when exists(select 1 from public.edt_phases x where x.edt_id=p.edt_id and x.statut in ('en_cours','terminee','fermee')) then 'En cours'
                  else 'Planifie' end;
 update public.suivi_des_edt set statut=v_parent,lifecycle_status=case when v_parent='Termine' then 'ferme' when v_parent='En cours' then 'actif' else 'planifie' end,updated_at=now() where id=p.edt_id;
 insert into public.operations_history(entity_type,entity_id,entity_reference,action,old_data,new_data,details,user_id)
 values('edt_lifecycle',p.edt_id::text,e.no_edt,'TRANSITION_PHASE_'||upper(p.phase_type),to_jsonb(p),to_jsonb(v_updated),v_current||' -> '||v_target,auth.uid());
 return to_jsonb(v_updated);
END;
END;
$function$

CREATE OR REPLACE FUNCTION public.transition_phase_edt_v132p1(p_phase_id bigint, p_action text, p_commentaire text DEFAULT NULL::text, p_anomalies jsonb DEFAULT '[]'::jsonb, p_photo_exception text DEFAULT NULL::text, p_exception_date text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.edt_phases%rowtype;e public.suivi_des_edt%rowtype;c public.campagnes_maitres%rowtype;oldp jsonb;open_count int;blocked_count int;photo_count int;next_status text;
BEGIN
IF (auth.uid() IS NOT NULL AND public.tos_current_role() IN ('Administrateur','Coordonnateur')) IS NOT TRUE THEN RAISE EXCEPTION 'canonical_rpc_role_denied' USING ERRCODE='42501';END IF;
IF (NOT EXISTS(SELECT 1 FROM public.utilisateurs actor_profile WHERE actor_profile.auth_user_id=auth.uid() AND lower(coalesce(actor_profile.statut,''))='actif' AND actor_profile.client_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.clients actor_owner WHERE actor_owner.id=actor_profile.client_id))) IS NOT TRUE THEN RAISE EXCEPTION 'canonical_actor_client_invalid' USING ERRCODE='42501';END IF;
IF (EXISTS(SELECT 1 FROM public.edt_phases sec_phase JOIN public.suivi_des_edt sec_edt ON sec_edt.id=sec_phase.edt_id WHERE sec_phase.id=p_phase_id AND (sec_phase.client_id IS NULL OR sec_phase.client_id=sec_edt.client_id) AND public.tos_table_resource_scope(sec_edt.client_id,NULL,sec_edt.campagne_id,NULL,false))) IS NOT TRUE THEN RAISE EXCEPTION 'phase_scope_denied' USING ERRCODE='42501';END IF;

BEGIN

  if public.current_app_role() not in ('Administrateur','Coordonnateur') then raise exception 'Permission insuffisante.' using errcode='42501';end if;
  select * into p from public.edt_phases where id=p_phase_id for update;if not found or p.phase_type not in ('installation','retrait') then raise exception 'Phase EDT P1 introuvable.';end if;
  select * into e from public.suivi_des_edt where id=p.edt_id for update;select * into c from public.campagnes_maitres where id=e.campagne_id;
  oldp:=to_jsonb(p);
  if p_action='demarrer' then
    if p.phase_type='retrait' and not exists(select 1 from public.edt_phases where edt_id=p.edt_id and phase_type='installation' and statut='fermee') then raise exception 'Installation non fermée.';end if;
    next_status:='en_cours';update public.edt_phases set statut=next_status,date_debut_reelle=coalesce(date_debut_reelle,now()),updated_at=now() where id=p.id;
  elsif p_action='terminer' then
    next_status:=case when p.phase_type='installation' then 'terminee' else 'termine' end;update public.edt_phases set statut=next_status,progression=100,date_fin_reelle=coalesce(date_fin_reelle,now()),commentaire=p_commentaire,anomalies=coalesce(p_anomalies,'[]'),updated_at=now() where id=p.id;
  elsif p_action='fermer' then
    select count(*) into open_count from public.edt_supports where edt_id=p.edt_id and phase_id=p.id and statut not in ('Terminé','Terminée','Complété','Complétée','Annulé');
    select count(*) into blocked_count from public.edt_supports where edt_id=p.edt_id and phase_id=p.id and (bloque or statut='Bloqué');
    select count(*) into photo_count from public.support_photos where edt_id=p.edt_id::text and lower(type_photo)=p.phase_type and coalesce(status,'active')='active';
    if p.progression<100 or open_count>0 then raise exception 'Éléments obligatoires incomplets.';end if;
    if photo_count=0 and coalesce(trim(p_photo_exception),'')='' then raise exception 'Photo requise ou exception documentée.';end if;
    if blocked_count>0 and jsonb_array_length(coalesce(p_anomalies,'[]'))=0 then raise exception 'Anomalies bloquantes non documentées.';end if;
    next_status:=case when p.phase_type='installation' then 'fermee' else 'ferme' end;
    update public.edt_phases set statut=next_status,closed_at=now(),closed_by=auth.uid(),report_ready_at=now(),commentaire=p_commentaire,anomalies=coalesce(p_anomalies,'[]'),photo_exception=p_photo_exception,updated_at=now() where id=p.id;
    insert into public.edt_phase_reports(edt_id,phase_id,phase_type,version,status,report_snapshot,generated_at,generated_by)
    select p.edt_id,p.id,p.phase_type,coalesce(max(version),0)+1,'brouillon',jsonb_build_object('edt_id',p.edt_id,'phase',p.phase_type,'closed_at',now()),now(),auth.uid() from public.edt_phase_reports where phase_id=p.id;
  elsif p_action='rouvrir' then
    if coalesce(trim(p_commentaire),'')='' then raise exception 'Motif de réouverture obligatoire.';end if;
    if p.closed_at is null then raise exception 'La phase n’est pas fermée.';end if;
    next_status:=case when p.phase_type='installation' then 'terminee' else 'termine' end;
    update public.edt_phases set statut=next_status,reopened_at=now(),reopened_by=auth.uid(),reopen_reason=p_commentaire,closed_at=null,closed_by=null,updated_at=now() where id=p.id;
    update public.edt_phase_reports set archived=true where phase_id=p.id and archived=false;
    update public.suivi_des_edt set lifecycle_status=case when p.phase_type='installation' then 'installation_terminee' else 'retrait_termine' end,lifecycle_closed_at=null,lifecycle_closed_by=null,updated_at=now() where id=p.edt_id;
  else raise exception 'Action de phase invalide.';end if;
  update public.suivi_des_edt set lifecycle_status=case when p.phase_type='installation' then case next_status when 'en_cours' then 'installation_en_cours' when 'terminee' then 'installation_terminee' when 'fermee' then 'attente_fin_campagne' else lifecycle_status end else case next_status when 'en_cours' then 'retrait_en_cours' when 'termine' then 'retrait_termine' when 'ferme' then 'retrait_termine' else lifecycle_status end end,updated_at=now() where id=p.edt_id;
  perform public.tdm_edt_audit_v132p1(p.edt_id,p.id,upper(p_action),oldp,(select to_jsonb(x) from public.edt_phases x where x.id=p.id),coalesce(p_commentaire,p_exception_date));
  return jsonb_build_object('ok',true,'phase_id',p.id,'statut',next_status);
END;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_visual_edt_association(p_visual_id bigint, p_phase_id bigint, p_remove_edt_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE links jsonb;
BEGIN
 IF auth.uid() IS NULL OR public.tos_current_role() IS DISTINCT FROM 'Administrateur' THEN RAISE EXCEPTION 'admin_visual_edt_assignment_required' USING ERRCODE='42501';END IF;
 PERFORM 1 FROM public.campagne_visuels_formats WHERE id=p_visual_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'visual_scope_denied' USING ERRCODE='42501';END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(a)),'[]') INTO links FROM public.visual_edt_associations a WHERE visual_id=p_visual_id AND (p_remove_edt_id IS NULL OR a.edt_id<>p_remove_edt_id) AND (p_phase_id IS NULL OR a.edt_id<>(SELECT edt_id FROM public.edt_phases WHERE id=p_phase_id));
 IF p_phase_id IS NOT NULL THEN links:=links||jsonb_build_array(jsonb_build_object('phase_id',p_phase_id));END IF;
 RETURN public.save_visual_edt_associations(p_visual_id,links);
END $function$

CREATE OR REPLACE FUNCTION public.validate_edt_report_requester_v1301()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_edt_client bigint;v_requester_client bigint;
begin
 select c.client_id into v_edt_client from public.suivi_des_edt e join public.campagnes_maitres c on c.id=e.campagne_id where e.id=new.edt_id;
 select u.client_id into v_requester_client from public.utilisateurs u where u.id=new.requester_contact_id;
 if v_edt_client is null then raise exception 'edt_client_scope_missing' using errcode='23514'; end if;
 if v_requester_client is null or v_requester_client<>v_edt_client then raise exception 'requester_client_mismatch' using errcode='23514'; end if;
 return new;
end$function$

CREATE OR REPLACE FUNCTION public.validate_edt_requester_v131()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_requester_client bigint;v_edt_client bigint;
begin
 if new.requester_contact_id is null then return new; end if;
 select client_id into v_requester_client from public.utilisateurs where id=new.requester_contact_id;
 select client_id into v_edt_client from public.campagnes_maitres where id=new.campagne_id;
 if v_requester_client is null or v_edt_client is null or v_requester_client<>v_edt_client then raise exception 'requester_client_mismatch' using errcode='23514'; end if;
 return new;
end$function$
